package com.gx.velveteclipse.tests;
import com.gx.velveteclipse.darkhour.*;import com.gx.velveteclipse.core.battle.*;import com.gx.velveteclipse.core.persona.*;import com.gx.velveteclipse.client.tartarus.*;
import net.minecraft.nbt.CompoundTag;import net.minecraft.network.FriendlyByteBuf;import io.netty.buffer.Unpooled;
import java.util.*;import java.nio.file.*;import java.awt.*;import java.awt.image.BufferedImage;
public final class TartarusMapAudit {
 private static int checks;private static void check(boolean b,String message){checks++;if(!b)throw new AssertionError(message);}
 public static void main(String[] args)throws Exception{
  PersonaRegistry.bootstrap();population();discovery();escape();clock();packetsAndPreview();
  System.out.println("PASS map-cycle: "+checks+" checks; finite population and save/reload, configurable counts, unique spawn clearance, personal exploration/reset, affinity discovery, escape success/failure, 30-minute deadline, map packet bounds and native HUD preview. Offline only.");
 }
 private static void population(){
  var p=new TartarusPopulation();var values=new HashSet<Integer>();for(int f=1;f<=250;f++){int n=p.count(8353,f);if(TartarusInteriorLayout.fixedFloor(f))check(n==(TartarusInteriorLayout.bossFloor(f)?1:0),"fixed floor spawn rule");else{check(n>=10&&n<=20,"10–20 ordinary enemies");values.add(n);check(n==p.count(200,f),"never reroll occupied generation");}}check(values.size()>5,"population varies between floors");
  var copy=TartarusPopulation.load(p.save());check(copy.count(100,1)==p.count(12,1),"count survives restart");p.range(32,32);check(p.count(0,1)==copy.count(0,1),"settings do not repopulate current floor");p.reset(1);check(p.count(0,1)==32,"new generation uses configured count");
  for(int[] range:new int[][]{{0,20},{20,10},{1,65}}){boolean rejected=false;try{p.range(range[0],range[1]);}catch(IllegalArgumentException ex){rejected=true;}check(rejected,"invalid range rejected");}
  for(int f:new int[]{1,2,24,26,49,249}){var plan=TartarusInteriorLayout.floor(100,f);var positions=TartarusPopulation.positions(plan);check(positions.size()>=64&&new HashSet<>(positions).size()==positions.size(),"unique command-capacity positions");var occupied=new HashSet<TartarusInteriorLayout.Point>();for(var c:plan.cells())if(c.y()==1||c.y()==2)occupied.add(new TartarusInteriorLayout.Point(c.x(),c.z()));for(var at:positions){check(plan.walkable().contains(at)&&!occupied.contains(at),"spawn has floor and two free blocks");check(Math.hypot(at.x()-plan.entry().x(),at.z()-plan.entry().z())>10,"safe arrival room");}}
  var state=new TartarusDungeonService.State();var slot=new CompoundTag();slot.m_128379_("defeated",true);state.slots.put("1:0",slot);state.population=p;var reload=TartarusDungeonService.State.load(state.m_7176_(new CompoundTag()));check(reload.slots.get("1:0").m_128471_("defeated")&&reload.population.count(0,1)==32,"defeat and quota survive world reload");
 }
 private static void discovery(){
  var chart=new TartarusMapData();chart.reset(2);check(!chart.known(1,-36,-36),"initial fog");chart.reveal(1,-36,-36);chart.seeChest(1,0);var restored=TartarusMapData.load(chart.save());check(restored.known(1,-36,-36)&&restored.chest(1,0),"exploration and seen chest persist");check(!restored.known(2,-36,-36)&&!new TartarusMapData().known(1,-36,-36),"floor and player isolation");check(!restored.reset(2)&&restored.known(1,-36,-36),"same cycle retains exploration");restored.reset(3);check(!restored.known(1,-36,-36)&&!restored.chest(1,0),"next cycle clears discovery");
  var k=new AffinityKnowledge();for(var e:Element.values())check(k.get("enemy",e)==null,"untested unknown");k.learn("enemy",new DamageOutcome(Element.FIRE,Affinity.WEAK,0,false,false,false,false,true));check(k.get("enemy",Element.FIRE)==null,"miss never reveals");for(var a:Affinity.values()){k.learn(a.name(),new DamageOutcome(Element.ICE,a,20,false,false,a==Affinity.REPEL,a==Affinity.DRAIN,false));check(AffinityKnowledge.decode(k.encode()).get(a.name(),Element.ICE)==a,"observed affinity persists: "+a);}
  check(new AffinityKnowledge().forEnemy("enemy").isEmpty(),"fresh boss phase contains no former weakness");
 }
 private static void escape(){
  for(double roll:new double[]{0,.999}){var player=new BattleCombatant(new UUID(0,1),"Player",BattleSide.PLAYERS,new PersonaInstance("izanagi",30,0,Set.of("ember")),100,100,100,100);var enemy=new BattleCombatant(new UUID(0,2),"Enemy",BattleSide.ENEMIES,new PersonaInstance("umbra_slime",1,0,Set.of("shade_bite")),100,100,100,100);var s=new BattleSession(java.util.List.of(player,enemy),new Random(){@Override public double nextDouble(){return roll;}});check(s.currentActor()==player,"player starts escape test");check(s.escapeChance()>=.2&&s.escapeChance()<=.8,"bounded odds");check(!s.attemptEscape(enemy.id())&&s.currentActor()==player,"wrong player cannot consume turn");check(s.attemptEscape(player.id())==(roll==0),"success and failure reachable");check(s.state()==BattleState.ACTIVE,"attempt does not abort multiplayer session");check((s.currentActor()==enemy)==(roll!=0),"failure consumes turn, success leaves detach to server");check(!player.guarding(),"failed escape adds no guard bonus");}
 }
 private static void clock(){
  var c=new DarkHourTimer();check(!c.advance(17999,999999)&&!c.running,"ordinary night unchanged");check(!c.advance(18000,500)&&c.remaining==1_800_000,"full thirty minutes");check(c.skyTime()==18000,"night clock starts at midnight");check(!c.advance(c.skyTime()+1,900000)&&c.remaining==900000,"half time");check(c.skyTime()==21000,"sky follows extended period");c=DarkHourTimer.load(c.save());check(c.running&&c.remaining==900000,"runtime persists over restart");check(!c.advance(c.skyTime()+1,899999)&&c.remaining==1,"not expired early");check(c.skyTime()<24000,"cannot reach dawn before expiry");check(c.advance(c.skyTime()+1,1)&&!c.running&&c.remaining==0,"exact deadline triggers evacuation");check(!c.advance(24000,50),"dawn cannot restart clock");check(!c.advance(42000,50)&&c.remaining==DarkHourTimer.DURATION,"next night fresh duration");check(c.advance(0,50)&&!c.running,"time set day ends immediately");
 }
 private static void packetsAndPreview()throws Exception{
  var plan=TartarusInteriorLayout.floor(8353,1);int width=97,height=97;byte[] tiles=new byte[(width*height+7)/8];var chart=new TartarusMapData();chart.reset(0);for(int x=-40;x<25;x+=6)for(int z=-40;z<12;z+=6)chart.reveal(1,x,z);
  for(var p:plan.walkable())if(chart.known(1,p.x(),p.z())){int i=(p.z()+48)*97+p.x()+48;tiles[i/8]|=(byte)(1<<(i%8));}
  var view=new TartarusMapNetwork.View(1,-48,-48,97,97,tiles,java.util.List.of(new TartarusMapNetwork.Marker(0,-12,-12),new TartarusMapNetwork.Marker(1,12,-36),new TartarusMapNetwork.Marker(2,-32,-32)));
  var b=new FriendlyByteBuf(Unpooled.buffer());try{TartarusMapNetwork.View.encode(view,b);var decoded=TartarusMapNetwork.View.decode(b);check(decoded.floor()==1&&Arrays.equals(decoded.tiles(),tiles)&&decoded.markers().equals(view.markers()),"map codec and markers");check(!decoded.tile(-1,0)&&!decoded.tile(0,98),"safe silhouette bounds");TartarusMapNetwork.Clock.encode(new TartarusMapNetwork.Clock(1800000),b);check(TartarusMapNetwork.Clock.decode(b).milliseconds()==1800000,"timer codec");check(!b.isReadable(),"packet fully consumed");b.writeInt(1);b.writeInt(0);b.writeInt(0);b.writeInt(129);b.writeInt(1);b.writeInt(17);boolean rejected=false;try{TartarusMapNetwork.View.decode(b);}catch(IllegalArgumentException ex){rejected=true;}check(rejected,"oversize packet rejected");}finally{b.release();}
  var image=new BufferedImage(1100,620,BufferedImage.TYPE_INT_ARGB);var g=image.createGraphics();g.setColor(new Color(0x061026));g.fillRect(0,0,1100,620);g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);var canvas=new Painter(g);TartarusMapDesign.paint(canvas,view,50,340,140,-35,-36,180,false);TartarusMapDesign.paint(canvas,view,440,65,410,-35,-36,180,true);canvas.text("EXPLORAÇÃO POR SETOR",35,25,24,0xFF79F4FF,0);g.dispose();Files.createDirectories(Path.of("build/reports/map"));javax.imageio.ImageIO.write(image,"png",Path.of("build/reports/map/minimap.png").toFile());
 }
 private record Painter(Graphics2D g) implements com.gx.velveteclipse.client.menu.MenuDesign.Canvas {
  public void fill(double x,double y,double w,double h,int c){g.setColor(new Color(c,true));g.fill(new java.awt.geom.Rectangle2D.Double(x,y,w,h));}
  public void poly(double[] a,int c){var p=new java.awt.geom.Path2D.Double();p.moveTo(a[0],a[1]);for(int i=2;i<a.length;i+=2)p.lineTo(a[i],a[i+1]);p.closePath();g.setColor(new Color(c,true));g.fill(p);}
  public void text(String s,double x,double y,double size,int c,double angle){var old=g.getTransform();g.translate(x,y);g.rotate(Math.toRadians(angle));g.setColor(new Color(c,true));g.setFont(new Font("SansSerif",Font.BOLD,(int)size));g.drawString(s,0,(int)(size*.8));g.setTransform(old);}
  public double width(String s,double size){return s.length()*size*.55;}public void item(int slot,double x,double y){}
 }
}
